Object.assign(MAT2N,{
"2mR1":DRETO("2mR1","Reto de los números hasta el 1000","yMix2a",["Soy un número entre 400 y 500. Mis decenas son 6 y mis unidades son la mitad de 6. ¿Quién soy?",["Estoy entre 400 y 500: mis centenas son 4.","Mis decenas: 6.","Mis unidades: la mitad de 6 = 3."],"Soy el 463."],"Todo lo puedo en Cristo."),
"2mR2":DRETO("2mR2","Reto de sumas y restas","yMix2b",["Tenía $85. Gasté $27 y luego me dieron $40. ¿Cuánto tengo?",["85 − 27 = 58.","58 + 40 = 98."],"Tengo $98."],"Todo lo puedo en Cristo."),
"2mR3":DRETO("2mR3","Reto de multiplicar y dividir","yMix2c",["Hay 4 cajas con 6 velas. Se reparten entre 3 capillas. ¿Cuántas velas le tocan a cada capilla?",["4 × 6 = 24 velas.","24 ÷ 3 = 8."],"8 velas a cada capilla."],"Todo lo puedo en Cristo."),
"2mR4":DRETO("2mR4","Reto de fracciones y dinero","yMix2d",["Tengo $100. Gasto la mitad en un libro y $15 en una estampa. ¿Cuánto me queda?",["La mitad de 100 es 50.","100 − 50 = 50.","50 − 15 = 35."],"Me quedan $35."],"Todo lo puedo en Cristo."),
"2mR5":DRETO("2mR5","Reto de geometría","yMix2e",["¿Cuántos lados tienen juntos 2 cuadrados y 3 triángulos?",["2 cuadrados: 2 × 4 = 8.","3 triángulos: 3 × 3 = 9.","8 + 9 = 17."],"17 lados."],"Todo lo puedo en Cristo."),
"2mR6":DRETO("2mR6","Reto de medida, tiempo y datos","yMix2f",["La Misa empieza a las 10:15 y dura 45 minutos. ¿A qué hora termina?",["10:15 + 45 minutos.","15 + 45 = 60 minutos = 1 hora."],"Termina a las 11:00."],"Todo lo puedo en Cristo.")});
